script:
/*RULE90*/
(function(){
var M=['يناير','فبراير','مارس','أبريل','مايو','يونيو','يوليو','أغسطس','سبتمبر','أكتوبر','نوفمبر','ديسمبر'];
function fd(d){return d&&!isNaN(d)?'<bdi dir="ltr">'+d.getDate()+'</bdi> '+M[d.getMonth()]+' <bdi dir="ltr">'+d.getFullYear()+'</bdi>':'—'}
function n(x){return '<bdi dir="ltr">'+x+'</bdi>'}
function iso(d){return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')}
function pd(v){var p=v.split('-');return new Date(+p[0],+p[1]-1,+p[2])}
var box=document.getElementById('s9pop'),trips=document.getElementById('s9trips'),k=0,inited=false;
var IT='<i class="isvg" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M4 7h16M10 11v6M14 11v6M6 7l1 13h10l1-13M9 7V4h6v3"/></svg></i>';
window.s9Add=function(){k++;var d=document.createElement('div');d.className='s9-trip';d.id='s9t'+k;d.innerHTML='<div class="s9-f"><label>تاريخ الدخول</label><input type="date" class="s9-in"></div><div class="s9-f"><label>تاريخ الخروج</label><input type="date" class="s9-out"></div><button type="button" class="s9-del" title="حذف الرحلة" aria-label="حذف الرحلة" onclick="this.parentNode.remove()">'+IT+'</button>';trips.appendChild(d)};
window.s9Open=function(){if(!inited){inited=true;document.getElementById('s9date').value=iso(new Date());s9Add()}box.classList.add('on');document.documentElement.style.overflow='hidden'};
window.s9Close=function(){box.classList.remove('on');document.documentElement.style.overflow=''};
box.addEventListener('click',function(e){if(e.target===box)s9Close()});
document.addEventListener('keydown',function(e){if(e.key==='Escape'&&box.classList.contains('on'))s9Close()});function hashOpen(){if(location.hash==='#schengen-calc'){var t=document.getElementById('schengen-calc');if(t)t.scrollIntoView({block:'center'});setTimeout(s9Open,350)}}hashOpen();window.addEventListener('hashchange',hashOpen);
function err(t){var e=document.getElementById('s9err');e.textContent=t;e.style.display=t?'block':'none'}
var OK='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="9"/><path d="M8 12l3 3 5-6"/></svg>',WARN='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 3 2 21h20z"/><path d="M12 10v5M12 18h.01"/></svg>',STOP='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="9"/><path d="M8 12h8"/></svg>';
window.s9Calc=function(){err('');var cv=document.getElementById('s9date').value;if(!cv){err('يرجى تحديد تاريخ الفحص المستهدف.');return}
var c=pd(cv),ws=new Date(c);ws.setDate(ws.getDate()-179);
var ins=trips.querySelectorAll('.s9-in'),outs=trips.querySelectorAll('.s9-out'),T=[];
for(var i=0;i<ins.length;i++){if(ins[i].value&&outs[i].value){var a=pd(ins[i].value),b=pd(outs[i].value);if(b<a){err('تاريخ الخروج لا يمكن أن يكون قبل تاريخ الدخول في إحدى الرحلات.');return}T.push([a,b])}else if(ins[i].value||outs[i].value){err('يرجى إكمال تاريخي الدخول والخروج لكل رحلة.');return}}
var used=0;for(var d=new Date(ws);d<=c;d.setDate(d.getDate()+1)){for(var j=0;j<T.length;j++){if(d>=T[j][0]&&d<=T[j][1]){used++;break}}}
var rem=90-used,reset=null;if(T.length){var mx=new Date(Math.max.apply(null,T.map(function(t){return t[1].getTime()})));reset=new Date(mx);reset.setDate(reset.getDate()+90)}
var R=document.getElementById('s9res');R.style.display='block';document.getElementById('s9used').innerHTML=n(used);document.getElementById('s9rem').innerHTML=n(Math.max(0,rem));document.getElementById('s9reset').innerHTML=reset?fd(reset):'يمكنك الدخول في أي وقت';
var tt=document.getElementById('s9rt'),ds=document.getElementById('s9desc');
if(used>90){R.className='s9-res over';tt.innerHTML=WARN+'تحذير: تجاوز للمدة المسموح بها';ds.innerHTML='لقد تجاوزت الحد الأقصى للإقامة المسموح به ('+n(90)+' يومًا) بمقدار <b>'+n(used-90)+'</b> يومًا خلال فترة الـ '+n(180)+' يومًا الممتدة من <b>'+fd(ws)+'</b> إلى <b>'+fd(c)+'</b>. هذا قد يعرّضك لغرامات أو حظر دخول.'}
else if(rem===0){R.className='s9-res full';tt.innerHTML=STOP+'تم استهلاك جميع الأيام المتاحة ('+n('90/90')+')';ds.innerHTML='لقد استهلكت جميع الأيام المتاحة لك في منطقة الشنغن خلال النافذة المتحركة الحالية. يجب البقاء خارج دول الشنغن حتى تبدأ الأيام القديمة بالسقوط، أو الانتظار حتى تاريخ <b>'+(reset?fd(reset):'—')+'</b> لإمكانية الدخول لقضاء إقامة كاملة.'}
else{R.className='s9-res ok';tt.innerHTML=OK+'الوضع سليم ومتاح للسفر';ds.innerHTML='بناءً على الحسابات في تاريخ <b>'+fd(c)+'</b> لديك <b>'+n(rem)+'</b> يومًا متبقيًا للإقامة في منطقة الشنغن خلال النافذة المتحركة الممتدة من <b>'+fd(ws)+'</b>.'}
R.scrollIntoView({behavior:'smooth',block:'nearest'})};
})();
